# frozen_string_literal: true

require_relative '../helper'
require 'zlib'
require_relative '../utils/ssl_socket_pair'
require 'async' if Gem::Version.new(RUBY_VERSION) >= Gem::Version.new('3.3')

# Randomized checks of BufferedReader. Each case streams generated bytes from a thread in
# random pieces while the reader's socket injects short reads, spurious waits, and waits that report
# a timeout although data is ready (what a fiber scheduler does when it resumes the reader late).
# Results are compared with IO#gets/IO#read semantics over the same bytes.
#
# FUZZ_SEED=<n> replays a run, FUZZ_ITERATIONS=<n> scales it, and FUZZ_STATS=1 prints coverage.
module BufferedReaderFuzz
  Reader = Dalli::Protocol::BufferedReader
  CHUNK = Reader::CHUNK_SIZE
  LARGE = Reader::LARGE_READ_SIZE
  SEED = Integer(ENV.fetch('FUZZ_SEED') { Random.new_seed.to_s })
  ITERATIONS = Integer(ENV.fetch('FUZZ_ITERATIONS', '8'))
  STATS = Hash.new(0)

  TRANSPORTS = %i[unix tcp ssl].freeze
  SELECTORS =
    if defined?(IO::Event::Selector)
      %i[URing EPoll KQueue Select].select { |name| IO::Event::Selector.const_defined?(name) }
    else
      []
    end
  SCHEDULERS = [nil, *SELECTORS].freeze

  # :exact never stalls, :stall stops the stream for good, :pauses stops it for under a timeout at a time.
  TIMEOUTS = { exact: 1.0, stall: 0.1, pauses: 0.2 }.freeze
  PAUSES = 3
  PAUSE_FRACTION = 0.4
  # How long past the timeout a stalled read may take to fail.
  TIMEOUT_SLACK = 0.1
  CASE_LIMIT = 30

  SIZES = [0, 1, 2, CHUNK - 1, CHUNK, CHUNK + 1, (2 * CHUNK) + 1, LARGE - 1, LARGE, LARGE + 1,
           (3 * LARGE) + CHUNK - 1].freeze
  PATTERNS = ["\r\n", "\r", "\n", "EN\r\n", "VA 12 k\r\n", "MN\r\n", "\0", "\xFF\xFE", 'é😀'].map(&:b).freeze
  SEPARATORS = ["\r\n", "\n"].freeze

  def self.now
    Process.clock_gettime(Process::CLOCK_MONOTONIC)
  end

  ##
  # IO#gets / IO#read semantics over a fixed byte string.
  ##
  class Model
    attr_reader :pos

    def initialize(stream)
      @stream = stream
      @pos = 0
    end

    def remaining
      @stream.bytesize - @pos
    end

    def rest
      @stream.byteslice(@pos..)
    end

    # Stream offset an operation must see before it can return, or nil when it needs EOF.
    def need(kind, arg)
      if kind == :gets
        index = @stream.byteindex(arg, @pos)
        index && (index + arg.bytesize)
      elsif arg.zero?
        @pos
      elsif arg <= remaining
        @pos + arg
      end
    end

    def apply(kind, arg)
      if kind == :gets
        return nil if remaining.zero?

        index = @stream.byteindex(arg, @pos)
        take(index ? index + arg.bytesize - @pos : remaining)
      else
        return take(0) if arg.zero?
        return nil if remaining.zero?

        take([arg, remaining].min)
      end
    end

    private

    def take(length)
      data = @stream.byteslice(@pos, length)
      @pos += length
      data
    end
  end

  ##
  # Fault injection and bookkeeping for one reader socket.
  ##
  class Faults
    # Recent reads and waits, for failure messages.
    HISTORY = 24

    attr_reader :waits, :delivered, :last_data_at

    def initialize(rng)
      @rng = rng
      @spurious = [0.0, 0.05, 0.2].sample(random: rng)
      @writable = [0.0, 0.02].sample(random: rng)
      @short = [0.0, 0.2, 0.5].sample(random: rng)
      @starve = [0.0, 0.3, 1.0].sample(random: rng)
      @waits = []
      @history = []
      @delivered = 0
      mark
    end

    def attach(sock)
      sock.singleton_class.prepend(Hooks)
      sock.instance_variable_set(:@fuzz_faults, self)
    end

    def mark
      @last_data_at = BufferedReaderFuzz.now
    end

    # The length to request, or the Symbol a spurious EAGAIN would return. The read after a poll
    # that found nothing is the reader's last check before failing, so it gets no spurious EAGAIN:
    # that would fail a read whose data is there, which no socket does.
    def read_length(sock, maxlen)
      STATS[:large_reads] += 1 if maxlen > CHUNK
      last_check = @last_check
      @last_check = false
      roll = @rng.rand
      spurious = spurious_result(sock, roll) unless last_check
      return spurious.tap { record(:read, maxlen, :spurious, spurious) } if spurious

      roll > 1 - @short ? @rng.rand(1..maxlen) : maxlen
    end

    # A TLS socket holding decrypted bytes always returns them, so it never gets a spurious EAGAIN.
    def spurious_result(sock, roll)
      return if sock.respond_to?(:pending) && sock.pending.positive?
      return :wait_readable if roll < @spurious

      :wait_writable if roll < @spurious + @writable
    end

    def read(maxlen, length)
      result = yield
      record(:read, maxlen, length, result.is_a?(String) ? result.bytesize : result.inspect)
      return result unless result.is_a?(String)

      @delivered += result.bytesize
      mark
      result
    end

    # Reports a timeout without waiting when the socket is ready and the roll says the scheduler
    # resumed the reader late; otherwise waits.
    def wait(sock, event, timeout)
      started = BufferedReaderFuzz.now
      @waits << [timeout, Fiber.blocking?, !Fiber.scheduler.nil?]
      starved = starve?(sock, event, timeout)
      result = starved ? nil : yield
      @last_check = timeout&.zero? && !result
      record(event, timeout, starved ? :starved : :waited, result ? :ready : result.inspect,
             (BufferedReaderFuzz.now - started).round(4))
      result
    end

    def history
      @history.map { |event| event.join(' ') }.join("\n")
    end

    private

    def starve?(sock, event, timeout)
      return false if timeout.nil? || timeout.zero? || @rng.rand >= @starve
      return false unless Fiber.blocking { IO.instance_method(event).bind_call(sock.to_io, 0) }

      STATS[:starved_waits] += 1
      true
    end

    def record(*event)
      @history << [(BufferedReaderFuzz.now - @last_data_at).round(4), *event]
      @history.shift if @history.size > HISTORY
    end
  end

  ##
  # Prepended to the reader's socket.
  ##
  module Hooks
    def read_nonblock(maxlen, buf = nil, exception: true)
      length = @fuzz_faults.read_length(self, maxlen)
      return length if length.is_a?(Symbol)

      @fuzz_faults.read(maxlen, length) { super(length, buf, exception: exception) }
    end

    def wait_readable(timeout = nil)
      @fuzz_faults.wait(self, :wait_readable, timeout) { super }
    end

    def wait_writable(timeout = nil)
      @fuzz_faults.wait(self, :wait_writable, timeout) { super }
    end
  end

  ##
  # Byte streams and the reads to run against them.
  ##
  module Scripts
    module_function

    def payload(rng)
      size = case rng.rand(6)
             when 0, 1 then SIZES.sample(random: rng)
             when 2 then rng.rand(1..(4 * CHUNK))
             when 3, 4 then rng.rand(1..(4 * LARGE))
             else rng.rand(1..1_500_000)
             end
      return rng.bytes(size) if rng.rand(3).zero?

      unit = PATTERNS.sample(rng.rand(1..3), random: rng).join.b
      (unit * ((size / unit.bytesize) + 1)).byteslice(0, size)
    end

    # meta-protocol-shaped replies: header line, value, terminator, then EN and EOF.
    def protocol_script(rng, with_large_value: false)
      stream = String.new(encoding: Encoding::BINARY)
      ops = protocol_values(rng, with_large_value).flat_map do |value|
        stream << "VA #{value.bytesize} t#{rng.rand(1000)}\r\n" << value << "\r\n"
        [[:gets, SEPARATORS.sample(random: rng)], [:read, value.bytesize], [:read, 2]]
      end
      stream << "EN\r\n"
      [stream, ops + [[:gets, "\r\n"], [:gets, "\r\n"], [:read, 1]]]
    end

    def protocol_values(rng, with_large_value)
      values = Array.new(rng.rand(1..4)) { payload(rng) }
      return values unless with_large_value && values.none? { |value| value.bytesize >= 3 * CHUNK }

      values << rng.bytes(rng.rand((3 * CHUNK)..(3 * LARGE)))
    end

    # Arbitrary bytes and operations, including reads of exactly the rest and past EOF.
    def random_script(rng)
      stream = Array.new(rng.rand(1..4)) { payload(rng) }.join.b
      model = Model.new(stream)
      ops = Array.new(rng.rand(4..24)) do
        op = rng.rand(3).zero? ? [:gets, SEPARATORS.sample(random: rng)] : [:read, read_size(rng, model.remaining)]
        model.apply(*op)
        op
      end
      [stream, ops]
    end

    def read_size(rng, remaining)
      case rng.rand(4)
      when 0 then remaining
      when 1 then remaining + rng.rand(1..CHUNK)
      when 2 then SIZES.sample(random: rng)
      else rng.rand(0..(3 * LARGE))
      end
    end
  end

  ##
  # Writer steps: [:write, bytes], [:pause, seconds], or [:stall] until released.
  ##
  module Plans
    module_function

    # The steps, plus the offset where a :stall stream stops.
    def build(mode, rng, stream, ops, index)
      case mode
      when :exact then [exact(rng, stream), nil]
      when :pauses then [pauses(rng, stream), nil]
      when :stall
        stall_at = index.even? ? stall_inside_large_read(rng, stream, ops) : rng.rand(0..stream.bytesize)
        [pieces(rng, stream.byteslice(0, stall_at)) + [[:stall]] + pieces(rng, stream.byteslice(stall_at..)), stall_at]
      end
    end

    def exact(rng, stream)
      pieces(rng, stream).flat_map { |step| rng.rand(8).zero? ? [[:pause, rng.rand * 0.002], step] : [step] }
    end

    # Pauses at distinct offsets, each shorter than the timeout.
    def pauses(rng, stream)
      cuts = Set.new
      cuts << rng.rand(1...stream.bytesize) while cuts.size < PAUSES
      pause = [:pause, TIMEOUTS[:pauses] * PAUSE_FRACTION]
      segments = [0, *cuts.sort, stream.bytesize].each_cons(2)
      segments.flat_map { |from, to| pieces(rng, stream.byteslice(from...to)) << pause }[0...-1]
    end

    # An offset at least two chunks into a value of three or more, so the reader is past its line
    # buffer and reading the value straight from the socket when the stream stops.
    def stall_inside_large_read(rng, stream, ops)
      model = Model.new(stream)
      reads = ops.filter_map do |kind, arg|
        start = model.pos
        model.apply(kind, arg)
        [start, arg] if kind == :read && arg >= 3 * CHUNK
      end
      start, length = reads.sample(random: rng)
      start + rng.rand((2 * CHUNK)...length)
    end

    def pieces(rng, bytes)
      steps = []
      offset = 0
      while offset < bytes.bytesize
        length = case rng.rand(5)
                 when 0 then rng.rand(1..16)
                 when 1 then [CHUNK - 1, CHUNK, CHUNK + 1, LARGE - 1, LARGE + 1].sample(random: rng)
                 when 2 then rng.rand(1..(2 * LARGE))
                 else rng.rand(1..400_000)
                 end
        steps << [:write, bytes.byteslice(offset, length)]
        offset += length
      end
      steps
    end
  end

  ##
  # Socket pairs and the thread that writes to the peer.
  ##
  module Wire
    module_function

    def socket_pair(transport)
      case transport
      when :unix then UNIXSocket.pair
      when :tcp
        server = TCPServer.new('127.0.0.1', 0)
        client = TCPSocket.new('127.0.0.1', server.local_address.ip_port)
        [client, server.accept]
      when :ssl then SSLSocketPair.open
      end
    ensure
      server&.close
    end

    def start_writer(peer, steps, release)
      Thread.new do
        Thread.current.report_on_exception = false
        steps.each do |step, arg|
          case step
          when :write then peer.write(arg)
          when :pause then sleep(arg)
          when :stall then release.pop
          end
        end
      rescue IOError, SystemCallError, OpenSSL::SSL::SSLError
        nil # the reader gave up and closed its end
      ensure
        close_quietly(peer)
      end
    end

    def close_quietly(io)
      io&.close
    rescue StandardError
      nil
    end
  end

  ##
  # One case: the reader under test, its faults, the model, and where the stream stalls.
  ##
  Case = Struct.new(:label, :reader, :faults, :model, :ops, :stall_at, :timeout) do
    def returned
      @returned ||= 0
    end

    def returned!(bytes)
      @returned = returned + (bytes ? bytes.bytesize : 0)
    end

    def buffered
      faults.delivered - returned
    end

    def stalls_before?(kind, arg)
      return false unless stall_at

      need = model.need(kind, arg)
      need.nil? || need > stall_at
    end
  end

  ##
  # Assertions shared by every case.
  ##
  module Checks
    def assert_same_bytes(expected, actual, context)
      return assert_nil(actual, context) if expected.nil?

      refute_nil actual, "#{context}: expected #{expected.bytesize} bytes, got nil"
      assert_equal Encoding::BINARY, actual.encoding, context
      return pass if expected == actual

      shorter = [expected.bytesize, actual.bytesize].min
      index = (0...shorter).find { |i| expected.getbyte(i) != actual.getbyte(i) } || shorter

      flunk "#{context}: expected #{expected.bytesize} bytes, got #{actual.bytesize}; first difference at byte #{index}"
    end

    # finish_request! discards the connection when pending? is true, so it must reflect exactly the
    # bytes taken from the socket but not yet returned.
    def assert_buffer_consistent(test_case, context)
      buffered = test_case.buffered

      assert_equal buffered.positive?, test_case.reader.pending?, "#{context}: pending? with #{buffered} bytes buffered"
    end

    def assert_fails_within_timeout(test_case, kind, arg, context)
      assert_raises(IO::TimeoutError, context) { test_case.reader.public_send(kind, arg) }
      hang = BufferedReaderFuzz.now - test_case.faults.last_data_at
      timeout = test_case.timeout
      STATS[:timeouts] += 1
      STATS[:max_hang_past_timeout] = [STATS[:max_hang_past_timeout], hang - timeout].max
      events = "; recent socket events (seconds since data, event, ...):\n#{test_case.faults.history}"

      assert_operator hang, :>=, timeout * 0.9, "#{context}: failed #{hang.round(3)}s after the last byte#{events}"
      assert_operator hang, :<=, timeout + TIMEOUT_SLACK,
                      "#{context}: failed #{hang.round(3)}s after the last byte with a #{timeout}s timeout#{events}"
    end

    # Every pause is shorter than the timeout, but together they outlast it.
    def assert_paused_through(started, label)
      paused = PAUSES * TIMEOUTS[:pauses] * PAUSE_FRACTION

      assert_operator BufferedReaderFuzz.now - started, :>=, paused * 0.9, "#{label}: finished before its pauses"
    end

    # Every wait is bounded by the reader's timeout and, under a fiber scheduler, lets other fibers
    # run. The only other wait is the zero-timeout poll that bypasses the scheduler after a wait
    # reports a timeout.
    def assert_bounded_waits(test_case)
      test_case.faults.waits.each do |wait_timeout, blocking, scheduled|
        bounded = wait_timeout&.zero? ? blocking : wait_timeout == test_case.timeout && !(scheduled && blocking)

        assert bounded, "#{test_case.label}: waited with timeout #{wait_timeout.inspect} " \
                        "(blocking: #{blocking.inspect}, scheduler: #{scheduled})"
      end
    end
  end

  ##
  # Runs cases; included into the spec.
  ##
  module Cases
    include Checks

    def fuzz(transport, scheduler, mode, count)
      with_scheduler(scheduler) do
        count.times do |index|
          label = "FUZZ_SEED=#{SEED} #{transport}/#{scheduler || 'no scheduler'}/#{mode} case #{index}"
          rng = Random.new(Zlib.crc32(label))
          Timeout.timeout(CASE_LIMIT, nil, "#{label} still running after #{CASE_LIMIT}s") do
            fuzz_case(transport, mode, index, rng, label)
          end
        end
      end
    end

    private

    def with_scheduler(selector)
      return yield unless selector

      reactor = Async::Reactor.new(selector: IO::Event::Selector.const_get(selector).new(Fiber.current))
      reactor.run(finished: false) do |task|
        yield
      ensure
        task.children&.each(&:stop)
      end.wait
    ensure
      Fiber.set_scheduler(nil) if selector
    end

    def fuzz_case(transport, mode, index, rng, label)
      stream, ops = script(rng, mode)
      steps, stall_at = Plans.build(mode, rng, stream, ops, index)
      sock, peer = Wire.socket_pair(transport)
      release = Thread::Queue.new
      writer = Wire.start_writer(peer, steps, release)
      faults = Faults.new(Random.new(rng.rand(2**32)))
      faults.attach(sock)
      timeout = TIMEOUTS.fetch(mode)
      check(Case.new(label, Reader.new(sock, timeout), faults, Model.new(stream), ops, stall_at, timeout), mode, rng)
    ensure
      Wire.close_quietly(sock)
      release&.push(true)
      assert writer.join(10), "#{label}: writer still running" if writer
    end

    def script(rng, mode)
      return Scripts.protocol_script(rng, with_large_value: mode == :stall) unless mode == :exact
      return Scripts.random_script(rng) if rng.rand(3).zero?

      stream, ops = Scripts.protocol_script(rng)
      # EOF partway through a reply.
      stream = stream.byteslice(0, rng.rand(0..stream.bytesize)) if rng.rand(4).zero?
      [stream, ops]
    end

    def check(test_case, mode, rng)
      started = BufferedReaderFuzz.now
      test_case.faults.mark
      STATS[:cases] += 1
      unless run_ops(test_case, rng) == :stalled
        assert_same_bytes(test_case.model.rest, drain(test_case, rng), "#{test_case.label} drain")
        assert_paused_through(started, test_case.label) if mode == :pauses
      end

      assert_bounded_waits(test_case)
    end

    def run_ops(test_case, rng)
      test_case.ops.each_with_index do |(kind, arg), index|
        context = "#{test_case.label} op #{index} #{kind}(#{arg.inspect})"
        expect_reply(test_case, rng)
        if test_case.stalls_before?(kind, arg)
          assert_fails_within_timeout(test_case, kind, arg, context)
          return :stalled
        end

        actual = read_reporting_history(test_case, kind, arg, context)
        test_case.returned!(actual)

        assert_same_bytes(test_case.model.apply(kind, arg), actual, context)
        assert_buffer_consistent(test_case, context)
        STATS[:ops] += 1
      end
    end

    # With nothing buffered, an op can start a new reply, whose first read then waits before reading
    # (on plain sockets). Marking that at random runs the wait under the injected faults.
    def expect_reply(test_case, rng)
      return if test_case.reader.pending? || rng.rand(2).zero?

      test_case.reader.expect_reply
      STATS[:expected_replies] += 1
    end

    def drain(test_case, rng)
      rest = String.new(encoding: Encoding::BINARY)
      size = -> { [1, CHUNK, LARGE + 1, 3 * LARGE].sample(random: rng) }
      while (chunk = read_reporting_history(test_case, :read, size.call, test_case.label))
        rest << chunk
      end
      rest
    end

    def read_reporting_history(test_case, kind, arg, context)
      test_case.reader.public_send(kind, arg)
    rescue IO::TimeoutError => e
      flunk "#{context}: unexpected #{e.message}; recent socket events " \
            "(seconds since data, event, ...):\n#{test_case.faults.history}"
    end
  end
end

if ENV['FUZZ_STATS']
  Minitest.after_run do
    puts "BufferedReader fuzz FUZZ_SEED=#{BufferedReaderFuzz::SEED}: #{BufferedReaderFuzz::STATS}"
  end
end

describe 'BufferedReader fuzz' do
  include BufferedReaderFuzz::Cases

  BufferedReaderFuzz::TRANSPORTS.each do |transport|
    BufferedReaderFuzz::SCHEDULERS.each do |scheduler|
      describe "over #{transport} #{scheduler ? "under Async with #{scheduler}" : 'without a fiber scheduler'}" do
        it 'matches IO#gets and IO#read on randomized streams and faults' do
          fuzz(transport, scheduler, :exact, BufferedReaderFuzz::ITERATIONS)
        end

        it 'fails within one timeout of the last byte when the stream stops' do
          fuzz(transport, scheduler, :stall, [BufferedReaderFuzz::ITERATIONS / 2, 2].max)
        end

        it 'keeps reading through pauses that are each shorter than the timeout' do
          fuzz(transport, scheduler, :pauses, [BufferedReaderFuzz::ITERATIONS / 8, 1].max)
        end
      end
    end
  end
end
